import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import math

# Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# Clean missing values
df['wicket_type'] = df['wicket_type'].fillna('')
df['player_dismissed'] = df['player_dismissed'].fillna('')
df['fielder'] = df['fielder'].fillna('')

# Convert over to float if it isn't
df['over'] = df['over'].astype(float)
df['match_no'] = df['match_no'].astype(int)

# Create phase column
def get_phase(over):
    if over < 6.0:
        return 'Powerplay (0-5)'
    elif over < 15.0:
        return 'Middle (6-14)'
    else:
        return 'Death (15-19)'

df['phase'] = df['over'].apply(get_phase)

# Basic Aggregates
total_deliveries = len(df)
total_matches = df['match_no'].nunique()
total_runs_of_bat = df['runs_of_bat'].sum()
total_extras = df['extras'].sum()
total_runs = total_runs_of_bat + total_extras
total_wickets = len(df[df['wicket_type'] != ''])
total_wides = df['wide'].sum()
total_noballs = df['noballs'].sum()
total_byes = df['byes'].sum()
total_legbyes = df['legbyes'].sum()

# Legal deliveries for over calculation
legal_deliveries = len(df[(df['wide'] == 0) & (df['noballs'] == 0)])
total_overs = legal_deliveries / 6.0

# KPIs
avg_runs_per_over = total_runs / total_overs if total_overs > 0 else 0
boundaries_count = len(df[df['runs_of_bat'].isin([4, 6])])
boundary_percentage = (boundaries_count / total_deliveries) * 100
dot_balls_count = len(df[(df['runs_of_bat'] == 0) & (df['extras'] == 0)])
dot_ball_percentage = (dot_balls_count / total_deliveries) * 100
extras_per_match = total_extras / total_matches if total_matches > 0 else 0
wickets_per_match = total_wickets / total_matches if total_matches > 0 else 0

# Helper function to convert plot to base64
def plot_to_base64(plt_obj, width=10, height=6):
    fig = plt_obj.gcf()
    fig.set_size_inches(width, height)
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=100)
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt_obj.close('all')
    return img_str

# Set seaborn style
sns.set_theme(style="whitegrid")

# HTML Content Generator
html = f"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>IPL 2026 Ball-by-Ball Analytics Report</title>
    <style>
        body {{
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            color: #333;
            line-height: 1.6;
            margin: 0;
            padding: 0;
            background-color: #f4f7f6;
        }}
        .container {{
            width: 90%;
            max-width: 1200px;
            margin: auto;
            padding: 20px;
        }}
        header {{
            background-color: #1a237e;
            color: white;
            padding: 30px 0;
            text-align: center;
            border-bottom: 5px solid #ffab00;
        }}
        h1 {{
            margin: 0;
            font-size: 2.5em;
        }}
        h2 {{
            color: #1a237e;
            border-bottom: 2px solid #ffab00;
            padding-bottom: 5px;
            margin-top: 40px;
        }}
        h3 {{
            color: #3949ab;
        }}
        .kpi-board {{
            display: flex;
            justify-content: space-between;
            flex-wrap: wrap;
            margin-top: 30px;
        }}
        .kpi-card {{
            background: white;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            padding: 20px;
            width: 18%;
            text-align: center;
            margin-bottom: 20px;
            border-top: 4px solid #1a237e;
        }}
        .kpi-value {{
            font-size: 2em;
            font-weight: bold;
            color: #1a237e;
            margin: 10px 0;
        }}
        .kpi-title {{
            font-size: 0.9em;
            color: #666;
            text-transform: uppercase;
        }}
        .section {{
            background: white;
            padding: 30px;
            margin-top: 30px;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }}
        table, th, td {{
            border: 1px solid #ddd;
        }}
        th, td {{
            padding: 12px;
            text-align: left;
        }}
        th {{
            background-color: #f5f5f5;
            color: #333;
        }}
        .chart-container {{
            text-align: center;
            margin: 30px 0;
        }}
        img {{
            max-width: 100%;
            height: auto;
            border: 1px solid #ddd;
            border-radius: 4px;
            padding: 5px;
            background: white;
        }}
    </style>
</head>
<body>
    <header>
        <h1>IPL 2026 Ball-by-Ball Analytics Report</h1>
        <p>A comprehensive analysis of batting, bowling, extras, and dismissal patterns.</p>
    </header>

    <div class="container">
        <!-- Dashboard KPIs -->
        <div class="kpi-board">
            <div class="kpi-card">
                <div class="kpi-title">Avg Runs Per Over</div>
                <div class="kpi-value">{avg_runs_per_over:.2f}</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-title">Boundary %</div>
                <div class="kpi-value">{boundary_percentage:.1f}%</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-title">Dot Ball %</div>
                <div class="kpi-value">{dot_ball_percentage:.1f}%</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-title">Extras Per Match</div>
                <div class="kpi-value">{extras_per_match:.1f}</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-title">Wickets Per Match</div>
                <div class="kpi-value">{wickets_per_match:.1f}</div>
            </div>
        </div>

        <!-- 1. Tournament Overview -->
        <div class="section" id="tournament-overview">
            <h2>1. Tournament Overview & Match Summary</h2>
            <p><strong>Total Matches Analyzed:</strong> {total_matches}</p>
            <p><strong>Total Deliveries Bowled:</strong> {total_deliveries}</p>
            <p><strong>Total Runs Scored:</strong> {total_runs}</p>
            <p><strong>Total Wickets Fallen:</strong> {total_wickets}</p>
            <p><strong>Total Extras Conceded:</strong> {total_extras} (Wides: {total_wides}, No-Balls: {total_noballs}, Byes: {total_byes}, Leg-Byes: {total_legbyes})</p>
            <p><strong>Venues Used:</strong> {', '.join(df['venue'].unique())}</p>
        </div>
"""

# --- 2. Batting Analysis ---
batting_stats = df.groupby('striker').agg(
    runs=('runs_of_bat', 'sum'),
    balls=('runs_of_bat', 'count'),
    fours=('runs_of_bat', lambda x: (x == 4).sum()),
    sixes=('runs_of_bat', lambda x: (x == 6).sum())
).reset_index()
batting_stats['strike_rate'] = (batting_stats['runs'] / batting_stats['balls'] * 100).round(2)
top_batters = batting_stats[batting_stats['balls'] >= 10].sort_values(by='runs', ascending=False).head(10)

plt.figure(figsize=(10, 6))
sns.barplot(data=top_batters, x='runs', y='striker', palette='Blues_r')
plt.title('Top Run Scorers (Min 10 balls faced)')
plt.xlabel('Total Runs')
plt.ylabel('Batter')
chart_batters = plot_to_base64(plt)

# Phase-wise scoring
phase_runs = df.groupby('phase')['runs_of_bat'].sum().reindex(['Powerplay (0-5)', 'Middle (6-14)', 'Death (15-19)'])
phase_balls = df.groupby('phase').size().reindex(['Powerplay (0-5)', 'Middle (6-14)', 'Death (15-19)'])
phase_sr = (phase_runs / phase_balls * 100).round(2)

plt.figure(figsize=(8, 5))
sns.barplot(x=phase_sr.index, y=phase_sr.values, palette='magma')
plt.title('Strike Rate by Match Phase')
plt.ylabel('Strike Rate')
chart_phase_sr = plot_to_base64(plt)

html += f"""
        <div class="section" id="batting-analysis">
            <h2>2. Batting Performance Analysis</h2>
            <h3>Top 10 Run-Scorers</h3>
            {top_batters.to_html(index=False, classes='table')}
            <div class="chart-container">
                <img src="data:image/png;base64,{chart_batters}" alt="Top Batters Chart">
            </div>

            <h3>Phase-wise Scoring</h3>
            <div class="chart-container">
                <img src="data:image/png;base64,{chart_phase_sr}" alt="Strike Rate by Phase">
            </div>
        </div>
"""

# --- 3. Bowling Analysis ---
bowling_stats = df.groupby('bowler').agg(
    balls=('match_no', 'count'),
    runs_conceded=('runs_of_bat', 'sum'),
    extras=('extras', 'sum'),
    wickets=('wicket_type', lambda x: (x != '').sum()),
    dots=('runs_of_bat', lambda x: (x == 0).sum()) # simplistic dot ball
).reset_index()

# Recalculate accurate dot balls and legal balls for economy
def get_bowler_stats(group):
    legal_balls = len(group[(group['wide'] == 0) & (group['noballs'] == 0)])
    runs = group['runs_of_bat'].sum() + group['wide'].sum() + group['noballs'].sum()
    dots = len(group[(group['runs_of_bat'] == 0) & (group['extras'] == 0)])
    wickets = len(group[group['wicket_type'] != ''])
    overs = legal_balls / 6.0
    econ = runs / overs if overs > 0 else 0
    dot_pct = (dots / len(group)) * 100 if len(group) > 0 else 0
    return pd.Series({{
        'overs': round(overs, 1),
        'runs_conceded': runs,
        'wickets': wickets,
        'economy': round(econ, 2),
        'dot_pct': round(dot_pct, 1)
    }})

bowler_detailed = df.groupby('bowler').apply(get_bowler_stats).reset_index()
top_bowlers = bowler_detailed[bowler_detailed['overs'] >= 2.0].sort_values(by=['wickets', 'economy'], ascending=[False, True]).head(10)

plt.figure(figsize=(10, 6))
sns.scatterplot(data=bowler_detailed[bowler_detailed['overs'] >= 2.0], x='economy', y='dot_pct', size='wickets', sizes=(50, 400), hue='wickets', palette='coolwarm')
plt.title('Bowler Effectiveness: Economy vs Dot Ball % (Size/Hue = Wickets)')
plt.xlabel('Economy Rate')
plt.ylabel('Dot Ball %')
chart_bowlers = plot_to_base64(plt)

# Dismissal types
dismissal_counts = df[df['wicket_type'] != '']['wicket_type'].value_counts()
plt.figure(figsize=(8, 5))
dismissal_counts.plot(kind='pie', autopct='%1.1f%%', colors=sns.color_palette("Set2"))
plt.title('Distribution of Dismissal Types')
plt.ylabel('')
chart_dismissals = plot_to_base64(plt)

html += f"""
        <div class="section" id="bowling-analysis">
            <h2>3. Bowling Performance Analysis</h2>
            <h3>Top 10 Bowlers (Min 2 Overs)</h3>
            {top_bowlers.to_html(index=False, classes='table')}
            <div class="chart-container">
                <img src="data:image/png;base64,{chart_bowlers}" alt="Bowler Effectiveness">
            </div>

            <h3>Dismissal Types Breakdown</h3>
            <div class="chart-container">
                <img src="data:image/png;base64,{chart_dismissals}" alt="Dismissals Chart">
            </div>
        </div>
"""

# --- 4. Team Comparison ---
team_batting = df.groupby('batting_team').agg(
    runs_scored=('runs_of_bat', 'sum'),
    extras_received=('extras', 'sum'),
    wickets_lost=('wicket_type', lambda x: (x != '').sum()),
    balls_faced=('match_no', 'count')
)
team_batting['total_runs'] = team_batting['runs_scored'] + team_batting['extras_received']
team_batting['run_rate'] = (team_batting['total_runs'] / (team_batting['balls_faced'] / 6)).round(2)

team_bowling = df.groupby('bowling_team').agg(
    runs_conceded=('runs_of_bat', 'sum'),
    extras_given=('extras', 'sum'),
    wickets_taken=('wicket_type', lambda x: (x != '').sum()),
    balls_bowled=('match_no', 'count')
)
team_bowling['total_runs_conceded'] = team_bowling['runs_conceded'] + team_bowling['extras_given']
team_bowling['economy_rate'] = (team_bowling['total_runs_conceded'] / (team_bowling['balls_bowled'] / 6)).round(2)

team_comp = pd.merge(team_batting, team_bowling, left_index=True, right_index=True).reset_index()
team_comp.rename(columns={{'batting_team': 'Team'}}, inplace=True)

plt.figure(figsize=(10, 6))
width = 0.35
x = np.arange(len(team_comp['Team']))
plt.bar(x - width/2, team_comp['run_rate'], width, label='Batting Run Rate', color='skyblue')
plt.bar(x + width/2, team_comp['economy_rate'], width, label='Bowling Economy', color='salmon')
plt.xticks(x, team_comp['Team'])
plt.title('Team Performance: Batting Run Rate vs Bowling Economy')
plt.legend()
chart_team_comp = plot_to_base64(plt)

html += f"""
        <div class="section" id="team-comparison">
            <h2>4. Team Performance Comparison</h2>
            {team_comp[['Team', 'total_runs', 'run_rate', 'wickets_lost', 'total_runs_conceded', 'economy_rate', 'wickets_taken']].to_html(index=False, classes='table')}
            <div class="chart-container">
                <img src="data:image/png;base64,{chart_team_comp}" alt="Team Comparison Chart">
            </div>
        </div>
"""

# --- 5. Extras Discipline ---
team_extras = df.groupby('bowling_team')[['wide', 'noballs', 'byes', 'legbyes']].sum()
team_extras['total_extras'] = team_extras.sum(axis=1)
team_extras = team_extras.sort_values(by='total_extras', ascending=False)

plt.figure(figsize=(10, 6))
team_extras[['wide', 'noballs', 'byes', 'legbyes']].plot(kind='bar', stacked=True, figsize=(10,6), colormap='viridis')
plt.title('Extras Conceded by Team')
plt.ylabel('Total Extras')
chart_extras = plot_to_base64(plt)

html += f"""
        <div class="section" id="extras-discipline">
            <h2>5. Extras & Bowling Discipline</h2>
            <p>Teams giving away the most extras impact their net scoring rates negatively. Here's a breakdown of discipline by bowling unit.</p>
            <div class="chart-container">
                <img src="data:image/png;base64,{chart_extras}" alt="Extras by Team">
            </div>
            {team_extras.reset_index().to_html(index=False, classes='table')}
        </div>
"""

# --- 6. Venue & Match Phase Insights ---
venue_stats = df.groupby(['venue', 'innings']).agg(
    total_runs=('runs_of_bat', lambda x: x.sum()),
    extras=('extras', 'sum'),
    wickets=('wicket_type', lambda x: (x != '').sum()),
    matches=('match_no', 'nunique')
).reset_index()
venue_stats['runs'] = venue_stats['total_runs'] + venue_stats['extras']
venue_stats['avg_score'] = (venue_stats['runs'] / venue_stats['matches']).round(1)

plt.figure(figsize=(12, 6))
sns.barplot(data=venue_stats, x='venue', y='avg_score', hue='innings', palette='Set1')
plt.xticks(rotation=45, ha='right')
plt.title('Average Innings Score by Venue (Setting vs Chasing)')
plt.ylabel('Average Score')
chart_venue = plot_to_base64(plt)

html += f"""
        <div class="section" id="venue-insights">
            <h2>6. Venue & Match Phase Insights</h2>
            <p>Analyzing average scores across different venues based on batting first (Innings 1) versus chasing (Innings 2).</p>
            <div class="chart-container">
                <img src="data:image/png;base64,{chart_venue}" alt="Venue Stats">
            </div>
            {venue_stats[['venue', 'innings', 'avg_score', 'wickets', 'matches']].to_html(index=False, classes='table')}
        </div>
    </div>
</body>
</html>
"""

with open('/app/output/final_report.html', 'w') as f:
    f.write(html)

print("Report generated successfully at /app/output/final_report.html")

